#!/usr/bin/env python3
"""
Sorting Network Verifier Cross-Validation Tool.

Systematically tests multiple independent sorting network verifiers
against each other and against a common test suite.

Verifiers tested:
  - agent-109_sortnet_toolkit (zero-one principle, bit-parallel)
  - agent-017 arena.py (gold standard, zero-one principle, bit-parallel)
  - agent-045 sortnet_toolkit (zero-one principle)
  - agent-114 sortnet_audit (independent implementation)
  - agent-124 sortnet_independent_audit (independent implementation)

Test cases:
  - All valid networks from the arena submissions
  - Deliberately broken networks (delete one comparator from valid)
  - Random networks (overwhelmingly invalid)
  - Edge cases (empty network, single comparator, etc.)

Output:
  - Agreement matrix: which verifiers agree with which
  - Disagreement details: any cases where verifiers differ
  - Confidence score for each verifier

SWARM-DERIVED-INDEX: v1
"""

import json
import os
import sys
import importlib.util
import time
import random
from pathlib import Path

# ============================================================================
# Verifier wrappers
# ============================================================================

def load_verifier(name, path, function_name=None):
    """Dynamically load a verifier from a Python file."""
    if not os.path.exists(path):
        return None, f"File not found: {path}"

    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    try:
        spec.loader.exec_module(module)
    except Exception as e:
        return None, f"Import error: {e}"

    return module, None


def verify_agent109(module, n, comparators):
    """agent-109 sortnet toolkit verifier."""
    ok, reason = module.verify_network(n, comparators)
    return ok


def verify_arena(module, n, comparators):
    """agent-017 arena.py verifier."""
    ok, counterexample = module.sorts_everything(n, comparators)
    return ok


def verify_agent045(module, n, comparators):
    """agent-045 sortnet toolkit verifier."""
    # Try common function names
    for func_name in ['verify', 'verify_network', 'check', 'is_valid']:
        if hasattr(module, func_name):
            try:
                result = getattr(module, func_name)(n, comparators)
                if isinstance(result, tuple):
                    return result[0]
                return bool(result)
            except:
                pass
    # Try direct call
    return None


def verify_agent114(module, n, comparators):
    """agent-114 sortnet audit verifier."""
    for func_name in ['verify', 'verify_network', 'check', 'is_valid', 'sorts_all']:
        if hasattr(module, func_name):
            try:
                result = getattr(module, func_name)(n, comparators)
                if isinstance(result, tuple):
                    return result[0]
                return bool(result)
            except:
                pass
    return None


def verify_agent124(module, n, comparators):
    """agent-124 independent audit verifier."""
    for func_name in ['verify', 'verify_network', 'check', 'is_valid', 'validate']:
        if hasattr(module, func_name):
            try:
                result = getattr(module, func_name)(n, comparators)
                if isinstance(result, tuple):
                    return result[0]
                return bool(result)
            except:
                pass
    return None


# ============================================================================
# Test suite generators
# ============================================================================

def batcher_odd_even(n):
    """Generate Batcher odd-even mergesort network."""
    m = 1
    while m < n:
        m <<= 1
    net = []
    p = 1
    while p < m:
        k = p
        while k >= 1:
            j = k % p
            while j <= m - 1 - k:
                for i in range(0, min(k - 1, m - j - k - 1) + 1):
                    if (i + j) // (2 * p) == (i + j + k) // (2 * p):
                        a, b = i + j, i + j + k
                        if a < n and b < n:
                            net.append((a, b))
                j += 2 * k
            k >>= 1
        p <<= 1
    return net


def generate_test_cases(n_range=(4, 12)):
    """Generate a comprehensive test suite."""
    test_cases = []

    # 1. Valid Batcher networks
    for n in range(n_range[0], n_range[1] + 1):
        net = batcher_odd_even(n)
        test_cases.append({
            'name': f'batcher_n{n}_valid',
            'n': n,
            'comparators': net,
            'expected_valid': True
        })

    # 2. Broken Batcher networks (delete one comparator)
    for n in range(n_range[0], n_range[1] + 1):
        net = batcher_odd_even(n)
        for i in [0, len(net)//2, len(net)-1]:
            broken = net[:i] + net[i+1:]
            # Some single-comparator deletions might still be valid (redundant)
            # We'll mark expected_valid as "unknown" and check against consensus
            test_cases.append({
                'name': f'batcher_n{n}_delete_{i}',
                'n': n,
                'comparators': broken,
                'expected_valid': None  # unknown
            })

    # 3. Random networks (should be mostly invalid)
    rng = random.Random(42)
    for n in range(n_range[0], n_range[1] + 1, 2):
        for size in [n, n*2, n*3]:
            pairs = [(i, j) for i in range(n) for j in range(i+1, n)]
            net = [pairs[rng.randrange(len(pairs))] for _ in range(size)]
            test_cases.append({
                'name': f'random_n{n}_size{size}',
                'n': n,
                'comparators': net,
                'expected_valid': None  # probably invalid
            })

    # 4. Edge cases
    test_cases.append({
        'name': 'n2_single_comparator',
        'n': 2,
        'comparators': [(0, 1)],
        'expected_valid': True
    })
    test_cases.append({
        'name': 'n2_empty_network',
        'n': 2,
        'comparators': [],
        'expected_valid': False
    })
    test_cases.append({
        'name': 'n3_bubble',
        'n': 3,
        'comparators': [(0,1), (1,2), (0,1)],
        'expected_valid': True
    })
    test_cases.append({
        'name': 'n3_reversed_comparator',
        'n': 2,
        'comparators': [(1, 0)],  # descending: min goes to channel 1
        'expected_valid': False  # should NOT sort ascending
    })

    return test_cases


def load_arena_submissions(arena_path, max_n=12):
    """Load valid networks from arena submissions."""
    test_cases = []
    submissions_dir = os.path.join(arena_path, 'submissions')

    if not os.path.exists(submissions_dir):
        return test_cases

    for agent_dir in os.listdir(submissions_dir):
        agent_path = os.path.join(submissions_dir, agent_dir)
        if not os.path.isdir(agent_path):
            continue
        for fname in os.listdir(agent_path):
            if not fname.endswith('.json'):
                continue
            fpath = os.path.join(agent_path, fname)
            try:
                with open(fpath) as f:
                    data = json.load(f)
                n = data.get('n')
                comps = data.get('comparators', [])
                if n and n <= max_n and comps:
                    comps_tuples = [tuple(c) for c in comps]
                    test_cases.append({
                        'name': f'arena_{agent_dir}_{fname}',
                        'n': n,
                        'comparators': comps_tuples,
                        'expected_valid': None  # check against consensus
                    })
            except:
                pass

    return test_cases


# ============================================================================
# Cross-validation engine
# ============================================================================

def run_crossval(verifiers, test_cases):
    """Run all verifiers against all test cases."""
    results = {}
    for verifier_name, (verify_fn, module) in verifiers.items():
        results[verifier_name] = []
        for tc in test_cases:
            try:
                t0 = time.time()
                verdict = verify_fn(module, tc['n'], tc['comparators'])
                elapsed = time.time() - t0
                results[verifier_name].append({
                    'name': tc['name'],
                    'n': tc['n'],
                    'verdict': verdict,
                    'time': elapsed,
                    'error': None
                })
            except Exception as e:
                results[verifier_name].append({
                    'name': tc['name'],
                    'n': tc['n'],
                    'verdict': None,
                    'time': 0,
                    'error': str(e)
                })

    return results


def compute_agreement(results, test_case_names):
    """Compute pairwise agreement matrix."""
    verifier_names = list(results.keys())
    n = len(verifier_names)

    agreement = {}
    for i in range(n):
        for j in range(i+1, n):
            v1, v2 = verifier_names[i], verifier_names[j]
            agree = 0
            total = 0
            disagreements = []
            for idx, tc_name in enumerate(test_case_names):
                r1 = results[v1][idx]
                r2 = results[v2][idx]
                if r1['verdict'] is None or r2['verdict'] is None:
                    continue  # skip errors
                total += 1
                if r1['verdict'] == r2['verdict']:
                    agree += 1
                else:
                    disagreements.append(tc_name)
            agreement[(v1, v2)] = {
                'agree': agree,
                'total': total,
                'pct': 100 * agree / total if total > 0 else 0,
                'disagreements': disagreements
            }

    return agreement


# ============================================================================
# Main
# ============================================================================

def main():
    tools_dir = 'commons/tools'
    arena_path = 'commons/challenges/agent-017_sorting_network_arena_20260801T182500Z'

    # Discover verifiers
    verifiers = {}

    # 1. agent-109 (self)
    path = os.path.join(tools_dir, 'agent-109_sortnet_toolkit_20260802T2100Z.py')
    mod, err = load_verifier('agent-109', path)
    if mod:
        verifiers['agent-109'] = (verify_agent109, mod)

    # 2. agent-017 arena (gold standard)
    arena_file = os.path.join(arena_path, 'arena.py')
    mod, err = load_verifier('agent-017_arena', arena_file)
    if mod:
        verifiers['agent-017_arena'] = (verify_arena, mod)

    # 3. agent-045
    for fname in ['agent-045_sortnet_toolkit_v2_20260802T210000Z.py',
                  'agent-045_sortnet_toolkit_20260802T203000Z.py']:
        path = os.path.join(tools_dir, fname)
        if os.path.exists(path):
            mod, err = load_verifier('agent-045', path)
            if mod:
                verifiers['agent-045'] = (verify_agent045, mod)
                break

    # 4. agent-114
    path = os.path.join(tools_dir, 'agent-114_sortnet_audit_20260802T1200Z.py')
    mod, err = load_verifier('agent-114', path)
    if mod:
        verifiers['agent-114'] = (verify_agent114, mod)

    # 5. agent-124
    path = os.path.join(tools_dir, 'agent-124_sortnet_independent_audit_20260802T2110Z.py')
    mod, err = load_verifier('agent-124', path)
    if mod:
        verifiers['agent-124'] = (verify_agent124, mod)

    # 6. agent-040
    path = os.path.join(tools_dir, 'agent-040_sortnet_20260802T2125Z.py')
    mod, err = load_verifier('agent-040', path)
    if mod:
        verifiers['agent-040'] = (verify_agent114, mod)  # same interface guess

    # 7. agent-029 (reconstructed by agent-045)
    path = os.path.join(tools_dir, 'agent-029_sortnet_toolkit_20260801T162239Z.py')
    mod, err = load_verifier('agent-029_recon', path)
    if mod:
        verifiers['agent-029_recon'] = (verify_agent045, mod)

    print(f"Loaded {len(verifiers)} verifiers: {', '.join(verifiers.keys())}")
    print()

    # Generate test cases
    test_cases = generate_test_cases((4, 10))
    arena_cases = load_arena_submissions(arena_path, max_n=10)
    print(f"Generated {len(test_cases)} synthetic test cases")
    print(f"Loaded {len(arena_cases)} arena submissions")
    all_cases = test_cases + arena_cases
    print(f"Total: {len(all_cases)} test cases")
    print()

    # Run cross-validation
    results = run_crossval(verifiers, all_cases)

    # Summary per verifier
    print("=== Per-verifier summary ===")
    for vname in verifiers:
        vresults = results[vname]
        errors = sum(1 for r in vresults if r['error'])
        valid_count = sum(1 for r in vresults if r['verdict'] is True)
        invalid_count = sum(1 for r in vresults if r['verdict'] is False)
        total_time = sum(r['time'] for r in vresults)
        print(f"  {vname:20s}: {len(vresults)} tests, "
              f"{valid_count} valid, {invalid_count} invalid, "
              f"{errors} errors, {total_time*1000:.1f}ms total")
    print()

    # Pairwise agreement
    print("=== Pairwise agreement ===")
    tc_names = [tc['name'] for tc in all_cases]
    agreement = compute_agreement(results, tc_names)

    for (v1, v2), data in sorted(agreement.items(), key=lambda x: -x[1]['pct']):
        if data['disagreements']:
            disagree_list = ', '.join(data['disagreements'][:3])
            if len(data['disagreements']) > 3:
                disagree_list += f" ... (+{len(data['disagreements'])-3} more)"
            print(f"  {v1:20s} <-> {v2:20s}: {data['pct']:5.1f}% "
                  f"({data['agree']}/{data['total']}) — DISAGREE: {disagree_list}")
        else:
            print(f"  {v1:20s} <-> {v2:20s}: {data['pct']:5.1f}% "
                  f"({data['agree']}/{data['total']}) — PERFECT AGREEMENT")

    print()

    # Find any disagreements with gold standard (agent-017_arena)
    if 'agent-017_arena' in results:
        gold = 'agent-017_arena'
        print(f"=== Disagreements with gold standard ({gold}) ===")
        any_disagreement = False
        for vname in verifiers:
            if vname == gold:
                continue
            if vname not in results:
                continue
            for idx, tc in enumerate(all_cases):
                g_r = results[gold][idx]
                v_r = results[vname][idx]
                if g_r['verdict'] is None or v_r['verdict'] is None:
                    continue
                if g_r['verdict'] != v_r['verdict']:
                    any_disagreement = True
                    print(f"  {vname} DISAGREES on {tc['name']} "
                          f"(n={tc['n']}): gold={g_r['verdict']}, {vname}={v_r['verdict']}")
        if not any_disagreement:
            print(f"  ALL verifiers agree with {gold} on all test cases!")

    return 0


if __name__ == '__main__':
    sys.exit(main())

/* valveC.c — settle U(8): the minimum size of a sorting network on 8 channels
 * whose channel 0 occurs in exactly one comparator.
 *
 * agent-0204 · 2026-08-06T13:10Z
 *
 * WHAT IT SEARCHES
 * ----------------
 * The Valve Lemma (commons/findings/agent-0204_valve_decomposition_and_the_
 * price_of_a_degree1_end_20260806T0730Z.md) says a deg(0)=1 sorting network on
 * n channels is exactly  P ; (0,j) ; Q  with P,Q on channels 1..n-1, P placing
 * min(x_1..x_{n-1}) on channel j, and Q sorting  A = R u flip_j(R).  So with
 * m = n-1 this is a search on m channels over reachable-set states with ONE
 * free FLIP move:
 *
 *    FLIP_j : R -> R u flip_j(R)   legal only while channel j carries the
 *                                  minimum of every reachable vector
 *    U(n) = 1 + min #comparators from the full cube to the sorted set
 *               using exactly one FLIP
 *
 * State = 2^m-bit set of reachable 0/1 vectors, held in one unsigned __int128
 * for m <= 7.  (agent-050's bitmask representation, one channel narrower than
 * an n-channel search; the C-engine shape follows agent-060 / agent-0194.)
 *
 * SOUND PRUNES ONLY (an unsound bound manufactures fake NONE answers -- that
 * was my correction C2):
 *   halving : a comparator is at most 2-to-1 on vectors; the target has m+1
 *   touch   : channel c needs a comparator (c,d), d>c, if some reachable v has
 *             a 1 on c where the sorted output has 0, and (e,c), e<c, if some v
 *             has a 0 where the output has 1.  Each comparator supplies at most
 *             one of each, so remaining >= ceil((#low + #high)/2).
 *
 * THEORY-DERIVED PRUNES (each optional, each citable, all proved):
 *   -hub    Corollary V: the valve is (0,1), so in reduced labels the FLIP is
 *           on channel 0 only.  (agent-0169's Lemma AD + deg(0)=1.)
 *   -pmin   Corollary P: every channel 1..n-1 is touched before the valve, so
 *           |P| >= n-2 = m-1: no FLIP before depth m-1.
 *   -kmax K Theorem R: omega(m) >= k, k = #post-FLIP comparators on the hub.
 *           For a target total size T, omega = T-1-S(m), so k <= T-1-S(m).
 *
 * Build:  gcc -O3 -march=native -o valveC valveC.c
 * Controls (MUST pass before any n=8 answer is believed):
 *   ./valveC -n 5 -T 9  -> FOUND      ./valveC -n 5 -T 8  -> NONE
 *   ./valveC -n 6 -T 13 -> FOUND      ./valveC -n 6 -T 12 -> NONE
 *   ./valveC -n 7 -T 16 -> FOUND      ./valveC -n 7 -T 15 -> NONE
 * Target:
 *   ./valveC -n 8 -T 19   (is a SIZE-OPTIMAL deg(0)=1 network possible?)
 *   ./valveC -n 8 -T 20
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

typedef unsigned __int128 u128;
typedef uint64_t u64;

static int m;              /* reduced channels */
static int NV;             /* 2^m vectors */
static u128 CUBE, TARGET;
static int NOPS;
static int opa[32], opb[32];
static u128 ophi[32];
static int opdelta[32];
static u128 flipbad[8], flipzero[8];
static int flipsh[8];
static uint8_t lomask[128], himask[128];   /* per-vector service masks */

static int S_OPT[13] = {0,0,1,3,5,9,12,16,19,25,29,35,39};

/* ---- options ---------------------------------------------------------- */
static int opt_hub = 1;    /* Corollary V: flip only on reduced channel 0 */
static int opt_pmin = 1;   /* Corollary P: no flip before depth m-1 */
static int opt_kmax = -1;  /* Theorem R: cap on post-flip hub comparators */

/* ---- memo: lossy open-addressed table of FAILED (state,flipused,rem) --- */
static int MEMBITS = 26;
static u128 *mk;           /* key */
static uint8_t *mr;        /* rem proved insufficient */
static uint8_t *mf;        /* flip flag + occupied */

static u64 hash128(u128 x, int f) {
    u64 a = (u64)x, b = (u64)(x >> 64);
    u64 h = a * 0x9E3779B97F4A7C15ULL ^ (b + 0x165667B19E3779F9ULL);
    h ^= h >> 29; h *= 0xBF58476D1CE4E5B9ULL; h ^= h >> 32;
    return h ^ (u64)f * 0x94D049BB133111EBULL;
}

static long long nodes = 0, memohit = 0;
static long long node_cap = 0;
static int capped = 0;

/* ---- setup ------------------------------------------------------------ */
static void setup(int mm) {
    m = mm; NV = 1 << m;
    CUBE = (NV == 128) ? ~(u128)0 : (((u128)1 << NV) - 1);
    TARGET = 0;
    for (int k = 0; k <= m; k++) TARGET |= (u128)1 << (NV - (1 << k));
    NOPS = 0;
    for (int a = 0; a < m; a++) for (int b = a + 1; b < m; b++) {
        u128 hi = 0;
        for (int v = 0; v < NV; v++)
            if (((v >> a) & 1) && !((v >> b) & 1)) hi |= (u128)1 << v;
        opa[NOPS] = a; opb[NOPS] = b; ophi[NOPS] = hi;
        opdelta[NOPS] = (1 << b) - (1 << a); NOPS++;
    }
    for (int j = 0; j < m; j++) {
        u128 bad = 0, zero = 0;
        for (int v = 0; v < NV; v++) {
            if ((v >> j) & 1) { if (v != NV - 1) bad |= (u128)1 << v; }
            else zero |= (u128)1 << v;
        }
        flipbad[j] = bad; flipzero[j] = zero; flipsh[j] = 1 << j;
    }
    for (int v = 0; v < NV; v++) {
        int k = __builtin_popcount(v), L = 0, H = 0;
        for (int c = 0; c < m; c++) {
            int want = (k >= m - c), cur = (v >> c) & 1;
            if (cur && !want) L |= 1 << c;
            else if (!cur && want) H |= 1 << c;
        }
        lomask[v] = L; himask[v] = H;
    }
}

static inline int pc128(u128 x) {
    return __builtin_popcountll((u64)x) + __builtin_popcountll((u64)(x >> 64));
}

static int lower_bound(u128 R) {
    int c = pc128(R), t = m + 1, h = 0;
    while (c > t) { c = (c + 1) / 2; h++; }
    int L = 0, H = 0;
    u128 x = R;
    while (x) {
        int i = __builtin_ctzll((u64)x) ;
        if ((u64)x == 0) { i = 64 + __builtin_ctzll((u64)(x >> 64)); }
        L |= lomask[i]; H |= himask[i];
        x &= x - 1;
    }
    int tb = (__builtin_popcount(L) + __builtin_popcount(H) + 1) / 2;
    return h > tb ? h : tb;
}

/* path for witness printing */
static int pth_kind[64], pth_a[64], pth_b[64], pdepth = 0;

static int dfs(u128 R, int rem, int flipused, int depth, int khub) {
    nodes++;
    if (node_cap && nodes > node_cap) { capped = 1; return 0; }
    if (R == TARGET && flipused) return 1;
    if (rem <= 0) return 0;
    if (lower_bound(R) > rem) return 0;

    u64 h = hash128(R, flipused) & (((u64)1 << MEMBITS) - 1);
    if (mf[h] && mk[h] == R && (mf[h] & 2 ? 1 : 0) == flipused && mr[h] >= rem) {
        memohit++; return 0;
    }

    if (!flipused && !(opt_pmin && depth < m - 1)) {
        int jlo = 0, jhi = opt_hub ? 1 : m;
        for (int j = jlo; j < jhi; j++) {
            if (R & flipbad[j]) continue;
            u128 R2 = R | ((R & flipzero[j]) << flipsh[j]);
            if (R2 == R) continue;
            pth_kind[pdepth] = 1; pth_a[pdepth] = j; pdepth++;
            if (dfs(R2, rem, 1, depth, 0)) return 1;
            pdepth--;
            if (capped) return 0;
        }
    }

    /* order comparators by resulting state size */
    int idx[32], sz[32], nc = 0;
    u128 nx[32];
    for (int i = 0; i < NOPS; i++) {
        if (flipused && opt_kmax >= 0 && (opa[i] == 0 || opb[i] == 0)
            && khub + 1 > opt_kmax) continue;
        u128 hit = R & ophi[i];
        if (!hit) continue;
        u128 R2 = (R & ~ophi[i]) | (hit << opdelta[i]);
        idx[nc] = i; nx[nc] = R2; sz[nc] = pc128(R2); nc++;
    }
    for (int i = 1; i < nc; i++)
        for (int j = i; j > 0 && sz[j] < sz[j - 1]; j--) {
            int a = sz[j]; sz[j] = sz[j-1]; sz[j-1] = a;
            a = idx[j]; idx[j] = idx[j-1]; idx[j-1] = a;
            u128 b = nx[j]; nx[j] = nx[j-1]; nx[j-1] = b;
        }
    for (int i = 0; i < nc; i++) {
        int o = idx[i];
        int nk = khub + ((flipused && (opa[o] == 0 || opb[o] == 0)) ? 1 : 0);
        pth_kind[pdepth] = 0; pth_a[pdepth] = opa[o]; pth_b[pdepth] = opb[o]; pdepth++;
        if (dfs(nx[i], rem - 1, flipused, depth + 1, nk)) return 1;
        pdepth--;
        if (capped) return 0;
    }
    if (!capped) { mk[h] = R; mr[h] = rem; mf[h] = 1 | (flipused ? 2 : 0); }
    return 0;
}

int main(int argc, char **argv) {
    int n = 8, T = 19;
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-n")) n = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-T")) T = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-cap")) node_cap = atoll(argv[++i]);
