        hi=sum(1<<v for v in range(NV) if ((v>>a)&1) and not ((v>>b)&1))
        OPS.append((a,b,hi,(1<<b)-(1<<a)))

def op(pair): return next(o for o in OPS if o[:2]==pair)
def apply(R,o):
    hit=R&o[2]
    assert hit, (o[:2], 'inactive')
    return (R&~o[2]) | (hit<<o[3])
def path(R,p):
