#!/usr/bin/env python3
"""v1.2 SAT encoder front end: v1.1 controls plus solver-model decoder.

Generate:
  python3 ...v1_2.py -n 8 -T 20 -o target.cnf
Decode SAT model (DIMACS 'v ... 0' or plain integer lines):
  python3 ...v1_2.py -n 8 -T 20 --decode solver.out --json witness.json
The decoder replays every Boolean input before emitting a certificate.
"""
import argparse, importlib.util, json
P='commons/tools/agent-075_sortnet_degree1_sat_20260807T0115Z.py'
spec=importlib.util.spec_from_file_location('satcore',P)
core=importlib.util.module_from_spec(spec); spec.loader.exec_module(core)

def selftest():
    e=core.Encoding(3,3); good=[(1,2),(0,1),(1,2)]
    A=core.assignment_for_network(e,good); cls=list(e.clauses())
    assert len(cls)==e.clause_count() and all(core.satisfied(c,A) for c in cls)
    bad=[(1,2),(1,2),(0,2)]; B=core.assignment_for_network(e,bad)
    failures=[c for c in cls if not core.satisfied(c,B)]
    assert failures and all(len(c)==1 for c in failures)
    # Synthetic solver model needs only selectors for decoding.
    model='s SATISFIABLE\n'+'v '+' '.join(map(str,sorted(A)))+' 0\n'
    net=decode_text(e,model)
    assert net==good and verify(e.n,net)==[]
    print(f'PASS: known sorter satisfies all {len(cls)} clauses')
    print(f'PASS: degree-1 non-sorter rejected by {len(failures)} final units')
    print('PASS: SAT model decodes and exhaustively replays')

def parse_true(text):
    out=set()
    for line in text.splitlines():
        line=line.strip()
        if not line or line[0] in 'cs': continue
        if line.startswith('v'): line=line[1:]
        for tok in line.split():
            try: z=int(tok)
            except ValueError: continue
            if z>0: out.add(z)
    return out

def decode_text(e,text):
    true=parse_true(text); net=[]
    for t in range(e.T):
        chosen=[e.ops[o] for o in range(e.C) if e.sel(t,o) in true]
        if len(chosen)!=1: raise ValueError(f'time {t}: expected 1 selector, got {chosen}')
        net.append(chosen[0])
    return net

def verify(n,net):
    bad=[]
    for q in range(1<<n):
        v=[(q>>c)&1 for c in range(n)]
        for a,b in net:
            if v[a]>v[b]: v[a],v[b]=v[b],v[a]
        if v!=sorted(v): bad.append(q)
    return bad

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('-n',type=int,default=8)
    ap.add_argument('-T',type=int,default=20); ap.add_argument('-o')
    ap.add_argument('--decode'); ap.add_argument('--json'); ap.add_argument('--selftest',action='store_true')
    a=ap.parse_args(); e=core.Encoding(a.n,a.T)
    if a.selftest: selftest(); return
    if a.decode:
        net=decode_text(e,open(a.decode).read()); bad=verify(a.n,net)
        deg=[0]*a.n
        for x,y in net: deg[x]+=1; deg[y]+=1
        if bad: raise SystemExit(f'DECODED MODEL FAILS on {len(bad)} inputs; first={bad[0]}')
        if deg[0]!=1: raise SystemExit(f'DECODED MODEL has deg0={deg[0]}, not 1')
        obj={'n':a.n,'size':len(net),'network':net,'degrees':deg,'boolean_failures':0}
        s=json.dumps(obj,indent=2)
        if a.json: open(a.json,'w').write(s+'\n')
        print(s); return
    if not a.o: ap.error('-o PATH required unless --decode/--selftest')
    print(f'writing vars={e.nvars} clauses={e.clause_count()} to {a.o}')
    core.write_dimacs(e,a.o); print('DONE')
if __name__=='__main__': main()

